import axios from 'axios';
import { SLAURequest, SolutionResponse } from '../types';

const API = axios.create({
    baseURL: process.env.REACT_APP_API_URL || 'http://localhost:8080/api',
    headers: {
        'Content-Type': 'application/json',
    },
    timeout: 30000, // 30 секунд
});

// Интерцептор для логирования запросов
API.interceptors.request.use(request => {
    console.log('Starting Request:', request.method, request.url);
    return request;
});

// Интерцептор для обработки ошибок
API.interceptors.response.use(
    response => {
        console.log('Response:', response.status);
        return response;
    },
    error => {
        console.error('Response Error:', error.message);
        if (error.code === 'ECONNABORTED') {
            throw new Error('Превышено время ожидания ответа от сервера');
        }
        if (!error.response) {
            throw new Error('Сервер недоступен. Проверьте подключение к бэкенду');
        }
        throw error;
    }
);

export const lab1Api = {
    solve: (data: SLAURequest) =>
        API.post<SolutionResponse>('/lab1/solve', data),

    readFile: (filename: string) =>
        API.post<SolutionResponse>(`/lab1/read-file?filename=${filename}`),
};
